H2-FuelConsumption.code:
public static void FuelConsumption()
{
    Console.Write("Geef het aantal liter in de tank voor de rit: ");
    double literBefore = Convert.ToDouble(Console.ReadLine());
    Console.Write("Geef het aantal liter in de tank na de rit: ");
    double literAfter = Convert.ToDouble(Console.ReadLine());
    Console.Write("Geef de kilometerstand van je auto voor de rit: ");
    double kmBefore = Convert.ToDouble(Console.ReadLine());
    Console.Write("Geef de kilometerstand van je auto na de rit: ");
    double kmAfter = Convert.ToDouble(Console.ReadLine());

    double consumption = (100 * (literBefore - literAfter) / (kmAfter - kmBefore));
