H3-AccessCode.code:
static public void AccessCode()
{
    Console.Write("Geef je naam: ");
    string name = Console.ReadLine();
    Console.Write("Geef je geboortejaar: ");
    string yearOfBirth = Console.ReadLine();
    Console.Write("Geef je postcode: ");
    string postalCode = Console.ReadLine();
    string password = name.Substring(name.Length - 2, 1).ToLower();
    password += name.Substring(name.Length - 1, 1).ToUpper();
    password += yearOfBirth.Substring(3, 1);
    password += Convert.ToInt32(postalCode.Substring(0, 1)) * Convert.ToInt32(postalCode.Substring(0, 1));
    Console.WriteLine($"Je wachtwoord is {password}");
}

