H4-PocketMoney.code:
public static void PocketMoney()
{
    int standardMoney = 20;
    Console.WriteLine("Wat waren je punten op 20?");
    int points = Convert.ToInt32(Console.ReadLine());
    double pocketMoney = 0;
    if (points > 15)
    {
        pocketMoney = standardMoney + standardMoney * 0.6;
    }
    else if (points > 10)
    {
        pocketMoney = ((points - 10) * 2) + standardMoney;
    }
    else if (points == 10)
    {
        pocketMoney = standardMoney;
    }
    else if (points > 7)
    {
        pocketMoney = standardMoney - standardMoney * 0.30;
    }
    else if (points > 5)
    {
        pocketMoney = standardMoney - ((10 - points) * 3);
    }
    else
    {
        pocketMoney = 0;
    }
    Console.WriteLine($"Je zakgeld bedraagt {pocketMoney:F1} euro.");
}

