public static void BinarySearch()
{
    string[] carBrands = { "Citroen", "Mercedes", "Peugeot", "BMW", "Toyota", "AstonMartin", "Ferrari", "Opel", "Lexus", "Wartburg" };

    int startIndex = 0;
    int endIndex = carBrands.Length;
    int midlleIndex;
    int index = -1;

    Console.WriteLine("Welke automerk wil U zoeken?");
    string searchBrand = Console.ReadLine();

    Array.Sort(carBrands);
    while (startIndex <= endIndex)
    {
        midlleIndex = startIndex + (endIndex - startIndex) / 2;
        if (carBrands[midlleIndex].CompareTo(searchBrand) < 0)
        {
            startIndex = midlleIndex + 1;
        }
        else if (carBrands[midlleIndex].CompareTo(searchBrand) > 0)
        {
            endIndex = midlleIndex - 1;
        }
        else
        {
            index = midlleIndex;
            startIndex = endIndex + 1;
        }
    }
    if (index == -1)
    {
        Console.WriteLine($"Je zocht {searchBrand}, jammer die is niet gevonden");
    }
    else
    {
        Console.WriteLine($"Je zocht {searchBrand}, die is gevonden op index {index}");

    }
}

