public static string StringToLower(string text)
{
    string convertedText = "";
    int character = 0;
    for (int i = 0; i < text.Length; i++)
    {
        character = Convert.ToInt32(text[i]);
        if (character >= Convert.ToInt32('A') && character <= Convert.ToInt32('Z'))
        {
            character = character + 32;
        }
        convertedText = convertedText + Convert.ToChar(character);
    }
    return convertedText;
}

public static string StringTrim(string text)
{
    string convertedText = "";
    for (int i = 0; i < text.Length; i++)
    {
        if (text[i] != ' ')
        {
            convertedText += text[i];
        }
    }
    return convertedText;
}

