public static void HeatmapKnightMovesMain()
{
    int[,] chessboard = new int[8, 8];

    Console.WriteLine("Hoeveel keer wil je je paard laten springen?");
    int numberOfMoves = Convert.ToInt32(Console.ReadLine());
    Console.WriteLine("Wat is de initiele positie van het paard (A1..H8)");
    string startPosition = Console.ReadLine();
    for (int i = 0; i < numberOfMoves; i++)
    {
        startPosition = Move(chessboard, startPosition);
    }

    Console.WriteLine("De heatmap ziet er als volgt uit:");
    for (int i = 7; i >= 0; i--)        // de rijen van ons schaakbord (1 is onder) 
    {
        for (int j = 0; j < 8; j++)     // de kolommen van ons schaakbord
        {
            Console.Write($"{chessboard[i, j]:D3} ");
        }
        Console.WriteLine();
    }
}

public static string Move(int[,] chessboard, string position)
{
    int positionColumn = position[0] - 65;//of (char)inPositie- 'A';                        // De kolommen in onze schakkbord array
    int positionRow = Convert.ToInt32(position.Substring(1, 1)) - 1;  // De rijen in onze schaakbord array
    int newPositionRow = 0;
    int newPositionColumn = 0;
    Random random = new Random();

    // 8 mogelijke keuzes
    bool validMove = false;
    while (!validMove)
    {
        int move = random.Next(8);
        // 2 naar links, 1 naar boven
        if (move == 0)
        {
            newPositionColumn = positionColumn - 2;
            newPositionRow = positionRow + 1;
        }
        // 1 naar links, 2 naar boven
        if (move == 1)
        {
            newPositionColumn = positionColumn - 1;
            newPositionRow = positionRow + 2;
        }
        // 1 naar rechts, 2 naar boven
        if (move == 2)
        {
            newPositionColumn = positionColumn + 1;
            newPositionRow = positionRow + 2;
        }
        // 2 naar rechts, 1 naar boven
        if (move == 3)
        {
            newPositionColumn = positionColumn + 2;
            newPositionRow = positionRow + 1;
        }
        // 2 naar rechts, 1 naar onder
        if (move == 4)
        {
            newPositionColumn = positionColumn + 2;
            newPositionRow = positionRow - 1;
        }
        // 1 naar rechts, 2 naar onder
        if (move == 5)
        {
            newPositionColumn = positionColumn + 1;
            newPositionRow = positionRow - 2;
        }
        // 1 naar links, 2 naar onder
        if (move == 6)
        {
            newPositionColumn = positionColumn - 1;
            newPositionRow = positionRow - 2;
        }
        // 2 naar links, 1 naar onder
        if (move == 7)
        {
            newPositionColumn = positionColumn - 2;
            newPositionRow = positionRow - 1;
        }
        if ((0 <= newPositionRow && newPositionRow < 8) &&
            (0 <= newPositionColumn && newPositionColumn < 8))
        {
            validMove = true;
        }
    }
    chessboard[newPositionRow, newPositionColumn]++;
    return $"{(char)(newPositionColumn + (int)'A')}{newPositionRow + 1}";
}

H9-ConwayGameOfLife.code:
// Buiten de methoden, in de klasse, staat het enum-type:
public enum CellStatus { Live, Dead }

public static void ConwayGameOfLifeMain()
{
    Console.WriteLine("Hoe groot is je bord (l = b)?");
    int numberOfCells = Convert.ToInt32(Console.ReadLine());
    CellStatus[,] board = new CellStatus[numberOfCells, numberOfCells];
    Console.WriteLine("Hoeveel generaties wil je laten zien?");
    int numberOfGenerations = Convert.ToInt32(Console.ReadLine());

    Initialize(board);
    Show(board);

    for (int i = 2; i <= numberOfGenerations; i++)
    {
        Thread.Sleep(2000);
        board = NextGeneration(board);
        Show(board);
    }
}

public static void Initialize(CellStatus[,] inArray)
{
    Random random = new Random();
    for (int i = 0; i < inArray.GetLength(0); i++)
    {
        for (int j = 0; j < inArray.GetLength(1); j++)
        {
            inArray[i, j] = (CellStatus)random.Next(2);
        }
    }
}

public static CellStatus[,] NextGeneration(CellStatus[,] inArray)
{
    CellStatus[,] newBoard = new CellStatus[inArray.GetLength(0), inArray.GetLength(1)];

    // Any live cell with fewer than two live neighbours dies, as if by underpopulation.
    // Any live cell with two or three live neighbours lives on to the next generation.
    // Any live cell with more than three live neighbours dies, as if by overpopulation.
    // Any dead cell with exactly three live neighbours becomes a live cell, as if by reproduction.

    for (int i = 0; i < inArray.GetLength(0); i++)
    {
        for (int j = 0; j < inArray.GetLength(1); j++)
        {
            int countNeighbours = CountNeighbours(inArray, i, j);
            if (inArray[i, j] == CellStatus.Live)
            {
                if (countNeighbours < 2)
                {
                    newBoard[i, j] = CellStatus.Dead;
                }
                else if (countNeighbours == 2 || countNeighbours == 3)
                {
                    newBoard[i, j] = CellStatus.Live;
                }
                else
                {
                    newBoard[i, j] = CellStatus.Dead;
                }
            }
            else
            {
                if (countNeighbours == 3)
                {
                    newBoard[i, j] = CellStatus.Live;
                }
                else
                {
                    newBoard[i, j] = CellStatus.Dead;
                }
            }
        }
    }
    return newBoard;
}

public static int CountNeighbours(CellStatus[,] inArray, int row, int column)
{
    int countLivingNeighbours = 0;
    // de 8 cellen rond de cel worden overlopen
    for (int i = row - 1; i <= row + 1; i++)
    {
        for (int j = column - 1; j <= column + 1; j++)
        {
            //als geen enkele voorwaarde hieronder waar is, wordt de cel gechecked
            //i of j mag niet <0; dat is wel zo voor een cel in de eerste rij en/of in de eerste kolom
            //i of j mag niet gelijk of groter zijn dan het aantal rijen/kolommen; dat is zo op de laatste rij of laatste kolom
            //i en j mag nietsamen 0 zijn want dan gaat het over de cel zelf
            if (!(i < 0 || j < 0 || i >= inArray.GetLength(0) || j >= inArray.GetLength(1) || (i == row && j == column)))
            {
                if (inArray[i, j] == CellStatus.Live)
                {
                    countLivingNeighbours++;
                }
            }
        }
    }
    return countLivingNeighbours;
}

public static void Show(CellStatus[,] inArray)
{
    Console.Clear();
    for (int i = 0; i < inArray.GetLength(0); i++)
    {
        for (int j = 0; j < inArray.GetLength(1); j++)
        {
            if (inArray[i, j] == CellStatus.Live)
            {
                Console.Write("O");
            }
            else
            {
                Console.Write(" ");
            }
        }
        Console.WriteLine();
    }
}

