public static void CentralAlignmentText()
{
    Console.WriteLine("Geef een tekst in:");
    string text = Console.ReadLine();
    int length = 0;
    do
    {
        Console.WriteLine($"Geef de gewenste lengte van de tekst op, die moet minimaal {text.Length} zijn.");
        length = Convert.ToInt32(Console.ReadLine());
    } while (length < text.Length);
    Console.WriteLine("Geef het padding karakter:");
    char character = Convert.ToChar(Console.ReadLine());
    Console.WriteLine(CentralAlignment(text, length, character));
}

public static string CentralAlignment(string text, int length, char character)
{
    string newText = text.PadLeft((length - text.Length) / 2 + text.Length, character);
    return newText.PadRight(length, character);
}

