public static void HangmanGame()
{
    string[] wordChoices = new string[] { "kerst", "vakantie", "corona", "sneeuw", "kroketten" };
    Random random = new Random();
    string wordToGuess = wordChoices[random.Next(wordChoices.Length)];
    char[] lettersToGuess = new char[wordToGuess.Length];
    lettersToGuess = wordToGuess.ToCharArray();
    bool guessed = false;
    char[] guessedLetters = new char[wordToGuess.Length];
    for (int i = 0; i < guessedLetters.Length; i++)
    {
        guessedLetters[i] = '*';
    }
    int attempts = 0;
    do
    {
        for (int i = 0; i < guessedLetters.Length; i++)
        {
            Console.Write(guessedLetters[i]);
        }
        Console.WriteLine();
        Console.WriteLine("Geef letter in, of typ het volledige woord indien je het denkt te weten:");
        string guess = Console.ReadLine();
        if (guess.Length > 1)
        {
            if (guess == wordToGuess)
            {
                Console.WriteLine("Correct! U heeft het juiste woord gevonden.");
                guessed = true;
            }
            else
            {
                Console.WriteLine("Niet correct! Probeer een letter te geven.");
            }
        }
        else
        {
            if (Array.IndexOf(lettersToGuess, Convert.ToChar(guess)) >= 0)
            {
                guessedLetters[Array.IndexOf(lettersToGuess, Convert.ToChar(guess))] = Convert.ToChar(guess);
            }
        }
        attempts++;
    } while (!guessed);
    Console.WriteLine($"Benodigde pogingen: {attempts}.");
}
